for level in bachelors diploma masters doctoral; do
  perl -MHTML::Entities -0777 -ne '"'
    while(/<a["'^>]+href="([''^"]+)"[''^>]*>(.*?)<'"\\/a>/sig){
      "'$h=$1; $t=$2; $t=~s/<[''^>]*>/ /g; $t=~s/'"\\s+/ /g; "'$t=~s/''^'"\\s+|\\s+"'$//g; $t=decode_entities($t);
      next unless $h =~ m{''^https://nimsuniversity'"\\.org/};
      next if "'$h =~ m{/(bachelors-programs|diploma-programs|masters-program|doctoral-programs|nims-(institute|school|college|marik)|news|about|downloads|phd-research|university|privacy|placement|campus|howtoapply|scholarship|foreign|faq|international|careers|employee|nims-placement|approvals|accreditations|vision|history|award|our-values|founder|hr-services|Public|nursing-college)(?:[/?#]|$)} && $h !~ m{/nims-(dental-college-hospital|institute-of-pharmacy)/[''^/]+$};
      my $ok = $t =~ /''^(B'"\\.|BBA|BCA|BAJMC|BDS|Bachelor|B\\.design|Diploma|PG Diploma|M\\.|MBA|MCA|MAJMC|MDS|MPT|Master|Ph\\.D|PhD)/i;
