/bin/bash -lc 'TMP_ROOT="${TMPDIR:-/tmp}"; python3 - <<'"'PY'
import os,glob
for level in ['bachelors','diploma','masters','doctoral']:
 p=os.path.join(os.environ.get('TMPDIR','/tmp'),f'nims-{level}.tsv')
 rows=[]
 for line in open(p):
  n,u=line.rstrip('\\n').split('\\t',1)
  if n.startswith('Ph.D') or n in {'Bachelors Programs','Diploma Programs','Masters Programs','Doctoral Programs'}: continue
  rows.append((n,u))
 print(level,len(rows),len({n for n,u in rows}),len({u for n,u in rows}))
 from collections import defaultdict
 d=defaultdict(list)
 for n,u in rows:d[n].append(u)
 for n,us in d.items():
  if len(us)>1: print('DUP',n,*us,sep='\\n  ')
PY"

